    return ask_runs - state.notes.get("forced_patch_at", 0) >= GAP


def _source_frame(failure):
    for frame in reversed(failure.get("frames") or []):
        path = (frame.get("file") or "").replace("\\", "/")
        if path and not path.startswith("tests/") and not path.split("/")[-1].startswith("test_"):
            return frame
    return {}


def _pick_failure(state):
    for failure in state.failures:
        if _source_frame(failure):
            return failure
    return state.failures[0] if state.failures else {}


def _candidates(state, tools, failure):
    files = state.files or []
    test_file = (failure.get("test") or "").split("::")[0]
    token = test_file.split("/")[-1]
    if token.startswith("test_"):
        token = token[5:]
    if token.endswith(".py"):
        token = token[:-3]

    def resolve(module):
        parts = [p for p in (module or "").split(".") if p]
