{
  "rationale": "All four failing tasks share one control pathology in the forced-patch step: the student returns a plausible search/replace block whose *file* is wrong (a non-existent path like 'ledgerly/payments/__init__.py' or 'src/moneyexpress/invoice.py'), especially when the traceback has no non-test source frame (plain AssertionErrors), so `_source_frame` yields {} and the student is asked to patch with an empty path/snippet. The edit is then rejected or applied to nothing and the run is wasted; the student later narrates a diagnosis and ends the task. Fix: (1) derive a target file deterministically inside the routine by searching the repository for the student's exact `search` text when the returned path is missing/not allowed/is a test file, so a correct search block lands on the correct module; (2) when there is no source frame, show the failing *test* frame's excerpt instead of an empty snippet so the student can still produce a usable block; (3) include the full (short) traceback frame chain and never repeat a failure already tried; (4) start forcing after 3 read-only student turns and allow up to 3 attempts, still reverting any patch that increases the failing count. All decisions are deterministic code; the student is only asked one short question.",
  "changes": [
    {
      "name": "forced-patch",
      "trigger_description": "Fires when the suite is failing, the student has spent >=3 turns without a successful source patch (or >=2 turns since the last forced attempt, up to 3 attempts). It asks the student one short question anchored on the deepest non-test traceback frame (or the failing test frame when the error is a bare AssertionError), resolves the target module by looking up the student's exact search text in the repository, applies the block, re-runs the whole suite and reverts if the failing count increases.",
      "routine_py": """"Force a focused patch when the student keeps reading files without editing anything.

After a few read-only student turns with a failing suite the long conversation makes the model
narrate a diagnosis instead of acting, and when the traceback has no source frame (a plain
AssertionError) the model hallucinates a module path. This routine interrupts with one short
question - the failing test, its error, the short frame chain and the code at the deepest
non-test frame (or the failing test frame when there is none) - resolves the target module by
searching the repository for the returned search text, applies the block and re-runs the suite,
reverting a patch that makes it worse. Never repeats a failure it already tried.
"""

NAME = "forced-patch"

MAX_TRIES = 3
FIRST_AFTER = 3
GAP = 2
PAD = 25
MAX_SCAN = 40


def applies(state) -> bool:
    if state.done or not state.failures:
        return False
    tries = state.notes.get("forced_patch_tries", 0)
    if tries >= MAX_TRIES:
        return False
    ask_runs = state.routine_runs.get("ask-student", 0)
    if tries == 0:
        return ask_runs >= FIRST_AFTER and not any(p.get("ok") for p in state.patches)
    return ask_runs - state.notes.get("forced_patch_at", 0) >= GAP


def _is_test_path(path) -> bool:
    p = (path or "").replace("\\", "/")
    name = p.rsplit("/", 1)[-1]
    return p.startswith("tests/") or name.startswith("test_") or "/tests/" in p


def _source_frame(failure) -> dict:
    for frame in reversed(failure.get("frames") or []):
        if not _is_test_path(frame.get("file")):
            return frame
    return {}


def _pick_failure(state) -> dict:
    tried = set(state.notes.get("forced_patch_tried") or [])
    for failure in state.failures:
        if failure.get("test") not in tried and _source_frame(failure):
            return failure
    for failure in state.failures:
        if failure.get("test") not in tried:
            return failure
    return state.failures[0]


def _excerpt(tools, path, line) -> str:
    if not path:
        return ""
    try:
        lines = tools.read_file(path).splitlines()
    except Exception:
        return ""
    if not lines:
        return ""
    center = max(1, int(line or 1))
    lo = max(0, center - 1 - PAD)
    hi = min(len(lines), center + PAD)
    return "\n".join(f"{i + 1}: {lines[i]}" for i in range(lo, hi))


def _test_excerpt(tools, failure) -> str:
    for frame in reversed(failure.get("frames") or []):
        if _is_test_path(frame.get("file")):
            return _excerpt(tools, frame.get("file"), frame.get("line"))
    return ""


def _resolve_target(state, tools, target, search) -> str:
    files = [p for p in (state.files or []) if p.endswith(".py")]
    t = (target or "").replace("\\", "/")
    for cand in (t, t[2:] if t.startswith("./") else t):
        if cand and cand in files and not _is_test_path(cand):
            try:
                if search and search in tools.read_file(cand):
                    return cand
            except Exception:
                pass
    if not search or len(search) < 8:
        return ""
    for path in [p for p in files if not _is_test_path(p)][:MAX_SCAN]:
        try:
            if search in tools.read_file(path):
                return path
        except Exception:
            continue
    return ""


def _prompt(failure, path, snippet, hint) -> str:
    err = "\n".join((failure.get("error") or "").strip().splitlines()[:5])[:700]
    frames = "\n".join(
        f"  {fr.get('file')}:{fr.get('line')} in {fr.get('function')}"
        for fr in (failure.get("frames") or [])[-6:]
    )
    body = f"Code from {path}:\n{snippet}" if snippet else f"Test code:\n{hint}"
    return (
        "A pytest test fails. Fix the source code (never edit tests/).\n"
        f"Failing test: {failure.get('test')}\n"
        f"Traceback frames:\n{frames}\n"
        f"Error:\n{err}\n\n{body}\n\n"
        "Reply with the file to change and one exact search/replace block copied verbatim "
        "from that file. If the traceback points at a helper, check where its argument came from."
    )


def _record(state, result) -> None:
    state.test_output = result.get("output", state.test_output)
    state.failures = result.get("failures", state.failures)
    if result.get("failed") == 0:
        state.last_full_run = {"passed": result.get("passed", 0), "failed": 0}
        state.done = True


def run(state, tools, student):
    state.notes["forced_patch_tries"] = state.notes.get("forced_patch_tries", 0) + 1
    state.notes["forced_patch_at"] = state.routine_runs.get("ask-student", 0)

    before = tools.run_tests()
    _record(state, before)
    if state.done:
        state.summary = "suite already passes; nothing forced"
        return state
    before_failed = int(before.get("failed") or 0)

    failure = _pick_failure(state)
    frame = _source_frame(failure)
    path = frame.get("file") or ""
    snippet = _excerpt(tools, path, frame.get("line"))
    hint = "" if snippet else _test_excerpt(tools, failure)

    try:
        answer = student.ask("patch", _prompt(failure, path, snippet, hint)) or {}
    except Exception as exc:
        state.summary = f"forced patch: student error {exc}"
        return state

    search = answer.get("search") or ""
    replace = answer.get("replace") or ""
    target = _resolve_target(state, tools, answer.get("file") or path, search)
    if not target or not search:
        state.notes.setdefault("forced_patch_tried", []).append(failure.get("test"))
        state.summary = "forced patch: no applicable patch returned"
        return state

    try:
        applied = tools.edit_file(target, search, replace)
    except Exception as exc:
        state.summary = f"forced patch: edit rejected ({exc})"
        return state
    if not applied.get("ok"):
        state.summary = f"forced patch: could not apply on {target}"
        return state

    state.patches.append({"file": target, "search": search, "replace": replace, "ok": True})
    after = tools.run_tests()
    _record(state, after)
    if not state.done and int(after.get("failed") or 0) > before_failed:
        try:
            undone = tools.edit_file(target, replace, search)
        except Exception:
            undone = {"ok": False}
        if undone.get("ok"):
            state.patches[-1]["ok"] = False
            state.patches[-1]["reverted"] = True
            _record(state, tools.run_tests())
            state.summary = f"forced patch on {target} reverted (suite got worse)"
            return state
    state.notes.setdefault("forced_patch_tried", []).append(failure.get("test"))
    state.summary = (f"forced patch on {target}: {after.get('passed')} passed, "
                     f"{after.get('failed')} failed")
    return state
