failing test, its source and the exact function named by the deepest non-test traceback frame -
applies the returned search/replace block and re-runs the suite. A patch that makes fewer tests
pass is reverted, and its frame is remembered so the next call targets a different function.
"""

NAME = "forced-patch"

MAX_TRIES = 3
FIRST_AFTER = 3
GAP = 2
PAD = 20


def applies(state) -> bool:
    if state.done or not state.failures:
        return False
    if state.notes.get("forced_patch_tries", 0) >= MAX_TRIES:
        return False
    if not any(_source_frame(f) for f in state.failures):
        return False
    asks = state.routine_runs.get("ask-student", 0)
    if state.notes.get("forced_patch_tries", 0) == 0:
        return asks >= FIRST_AFTER
    return asks - state.notes.get("forced_patch_at", 0) >= GAP


def _source_frame(failure) -> dict:
    frames = failure.get("frames") or []
    for frame in reversed(frames):
        path = (frame.get("file") or "").replace("\\", "/")
        if path and not path.startswith("tests/") and not path.startswith("test_"):
            return frame
    return {}


def _pick_failure(state) -> dict:
    tried = state.notes.get("fp_tried", [])
    fallback = {}
    for failure in state.failures:
        frame = _source_frame(failure)
        if not frame:
            continue
        if not fallback:
            fallback = failure
        key = f"{frame.get('file')}:{frame.get('function')}"
        if key not in tried:
            return failure
    return fallback or (state.failures[0] if state.failures else {})


def _excerpt(tools, path, line) -> str:
    if not path:
        return ""
    try:
        lines = tools.read_file(path).splitlines()
    except Exception:
        return ""
    if not lines:
        return ""
    center = max(0, min(int(line or 1) - 1, len(lines) - 1))
    start = 0
    for i in range(center, -1, -1):
        s = lines[i]
        if s[:1] not in (" ", "\t") and (s.startswith("def ") or s.startswith("class ")
                                         or s.startswith("async def ")):
            start = i
            break
    end = len(lines)
    for j in range(start + 1, len(lines)):
        s = lines[j]
        if s[:1] not in (" ", "\t") and (s.startswith("def ") or s.startswith("class ")
                                         or s.startswith("async def ")):
            end = j
            break
    return "\n".join(f"{k + 1}: {lines[k]}" for k in range(start, end))[:1800]


def _prompt(state, failure, path, snippet, test_text) -> str:
    err = "\n".join((failure.get("error") or "").strip().splitlines()[:4])[:500]
    others = [f.get("test") for f in state.failures if f.get("test") != failure.get("test")]
    tail = "Other failing tests: " + ", ".join(others[:6]) if others else ""
    return (
        "A test in this repository fails. Fix the bug in the source function shown below.\n"
        f"Failing test: {failure.get('test')}\n"
        f"Error:\n{err}\n{tail}\n\n"
        f"Test source:\n{test_text}\n\n"
        f"Source function in {path}:\n{snippet}\n\n"
        "Answer with the file to change and one exact search/replace block copied verbatim from "
        "that source function. Never edit tests/."
    )


def _record(state, result) -> None:
    state.test_output = result.get("output", state.test_output)
    state.failures = result.get("failures", state.failures)
    if result.get("failed") == 0:
        state.last_full_run = {"passed": result.get("passed", 0), "failed": 0}
        state.done = True


def run(state, tools, student):
    state.notes["forced_patch_tries"] = state.notes.get("forced_patch_tries", 0) + 1
    state.notes["forced_patch_at"] = state.routine_runs.get("ask-student", 0)

    before = tools.run_tests()
    _record(state, before)
    if state.done:
        state.summary = "suite already passes; nothing forced"
        return state
    before_passed = int(before.get("passed") or 0)

    failure = _pick_failure(state)
    frame = _source_frame(failure)
    path = (frame.get("file") or "").replace("\\", "/")
    snippet = _excerpt(tools, path, frame.get("line"))

    test_file = ""
    for fr in reversed(failure.get("frames") or []):
        cand = (fr.get("file") or "").replace("\\", "/")
        if cand.startswith("tests/") or cand.startswith("test_"):
            test_file = cand
            break
    try:
        test_text = "\n".join(tools.read_file(test_file).splitlines()[:60]) if test_file else ""
    except Exception:
        test_text = ""

    try:
        answer = student.ask("patch", _prompt(state, failure, path, snippet, test_text)) or {}
    except Exception as exc:
        state.summary = f"forced patch: student error {exc}"
        return state

    target = (answer.get("file") or path).replace("\\", "/")
    search = answer.get("search") or ""
    replace = answer.get("replace") or ""
    if not target or not search:
        state.summary = "forced patch: no usable patch returned"
        return state

    tried = state.notes.setdefault("fp_tried", [])
    key = f"{path}:{frame.get('function')}"
    if path and key not in tried:
        tried.append(key)

    try:
        applied = tools.edit_file(target, search, replace)
    except Exception as exc:
        state.summary = f"forced patch: edit rejected ({exc})"
        return state
    if not applied.get("ok"):
        state.summary = f"forced patch: could not apply on {target}"
        return state

    state.patches.append({"file": target, "search": search, "replace": replace, "ok": True})
    after = tools.run_tests()
    _record(state, after)
    if not state.done and int(after.get("passed") or 0) < before_passed:
        try:
            undone = tools.edit_file(target, replace, search)
        except Exception:
            undone = {"ok": False}
        if undone.get("ok"):
            state.patches[-1]["ok"] = False
            state.patches[-1]["reverted"] = True
            _record(state, tools.run_tests())
            state.summary = f"forced patch on {target} reverted (fewer tests pass)"
            return state
    state.summary = (f"forced patch on {target}: {after.get('passed')} passed, "
                     f"{after.get('failed')} failed")
    return state
