# forced-patch

Interrupts a read-only student with a single focused patch question. It shows the failing test,
its error, the test body (which encodes the expected semantics) and the source file around the
non-test traceback frame, asks for one exact search/replace block, applies it and re-runs the
suite. Patches that were already tried and reverted are listed so the model does not repeat them,
and any patch that does not reduce the failing count is undone. It fires at most MAX_TRIES times,
once every GAP student turns.
",
      "requested_permissions": {
        "read": ["**"],
        "write": ["src/**"],
        "commands": ["python -m pytest"],
        "network": false
      }
    },
    {
      "name": "localize-patch",
      "trigger_description": "There are failures whose traceback frames are all in tests/ (blind failures), the student has had at least FIRST_AFTER turns, and this routine has run fewer than MAX_TRIES times.",
      "routine_py": "NAME = "localize-patch"

MAX_TRIES, FIRST_AFTER, CAP = 3, 3, 70


def _is_test(path):
    p = (path or "").replace("\\", "/")
    return p.startswith("tests/") or p.startswith("test_")


def _blind(state):
    out = []
    for f in state.failures:
        if not [fr for fr in (f.get("frames") or []) if not _is_test(fr.get("file"))]:
            out.append(f)
    return out


def applies(state):
    if state.done or not state.failures:
        return False
    if state.notes.get("lp_tries", 0) >= MAX_TRIES:
        return False
    if not _blind(state):
        return False
    return state.routine_runs.get("ask-student", 0) >= FIRST_AFTER


def _test_file(failure):
    frames = failure.get("frames") or []
    for fr in list(reversed(frames)) + frames:
        if _is_test(fr.get("file")):
            return (fr.get("file") or "").replace("\\", "/")
    return ""


def _modules(text):
    raw_lines = []
    for raw in (text or "").splitlines():
        line = raw.strip()
        if line.startswith("from ") and " import " in line:
            raw_lines.append(line[5:].split(" import ")[0])
        elif line.startswith("import "):
            for part in line[7:].split(","):
                raw_lines.append(part.split(" as ")[0])
    mods = []
    for m in raw_lines:
