    """Free parts of `window` not covered by any busy range."""
    free: list[TimeRange] = []
    cursor = window.start
    for r in merge(busy):
        if r.end <= cursor or r.start >= window.end:
            continue
        if r.start > cursor:
            free.append(TimeRange(cursor, r.start))
        cursor = max(cursor, r.end)
    if cursor < window.end:
